// Wake-orchestrator state API -- live readout of the portable bundle's state.
// Read-only. n8n Code node: require('fs') allowed (same as wf-llm-health). The
// bundle must be mounted into the n8n container; WAKE_BUNDLE_DIR overrides the
// default path. Bearer-gated (defense in depth; the NAS being LAN/Funnel-only is
// the real boundary). Every value traces to a real file -- no painted status.
const fs = require('fs');
const BUNDLE = process.env.WAKE_BUNDLE_DIR || '/data/poetech-portable';
const STATE = BUNDLE + '/state';
const BEARER_FILE = '/home/node/.n8n/n8n-webhook-bearer.txt';
function exists(p){ try { fs.accessSync(p); return true; } catch (e) { return false; } }
function read(p){ try { return fs.readFileSync(p, 'utf8'); } catch (e) { return ''; } }

const expected = read(BEARER_FILE).trim();
const input = $input.first().json || {};
const headers = (input.headers && typeof input.headers === 'object') ? input.headers : {};
const auth = String(headers.authorization || headers.Authorization || '');
const presented = auth.replace(/^Bearer\s+/i, '').trim();
if (expected && presented !== expected) return [{ json: { ok: false, error: 'unauthorized' } }];

const env = read(BUNDLE + '/.env');
function envNum(k){ const m = env.match(new RegExp('^' + k + '\\s*=\\s*([0-9.]+)', 'm')); return m ? Number(m[1]) : 0; }
const perTask = envNum('BUDGET_PER_TASK_USD');
const daily = envNum('BUDGET_DAILY_USD');
const day = new Date().toISOString().slice(0, 10);
const spent = Number((read(STATE + '/spend-' + day + '.txt') || '').trim()) || 0;

const killSwitch = exists(STATE + '/KILL_SWITCH') ? 'engaged' : 'clear';
const armed = exists(STATE + '/ARMED');
const wakeSummon = exists(STATE + '/WAKE_SUMMON');
const lock = exists(STATE + '/orchestrator.lock') ? 'held' : 'free';

const now = Date.now();
let handoffs = [];
try {
  const dir = STATE + '/handoffs';
  for (const f of fs.readdirSync(dir).filter(x => x.endsWith('.json'))) {
    try {
      const h = JSON.parse(read(dir + '/' + f));
      const w = h.wake_at || {};
      let due = false, reason = 'pending';
      const nb = w.not_before ? Date.parse(w.not_before) : null;
      if (nb && now < nb) { due = false; reason = 'before not_before'; }
      else if (w.at) { const t = Date.parse(w.at); due = Number.isFinite(t) && now >= t; reason = due ? 'time reached' : 'waiting'; }
      else if (w.after_seconds) { const b = Date.parse(h.issued_at); const t = b + w.after_seconds * 1000; due = Number.isFinite(b) && now >= t; reason = due ? 'delay elapsed' : 'waiting'; }
      else if (w.condition) { due = false; reason = 'condition (host router decides)'; }
      handoffs.push({ id: h.id || f, lane: h.lane || '', task: h.task || '', issued_by: h.issued_by || '', suggested_vendor: h.suggested_vendor || 'auto', wake_at: w, due, due_reason: reason });
    } catch (e) {}
  }
} catch (e) {}

let events = [], summons = [];
try {
  const lines = (read(BUNDLE + '/events/events.jsonl') || '').split('\n').filter(Boolean);
  for (const ln of lines.slice(-50).reverse()) {
    try {
      const e = JSON.parse(ln);
      events.push({ ts: e.ts, event: e.event, detail: e.detail });
      if (e.event === 'wake_summon_done') {
        const d = String(e.detail || '');
        const g = (re) => (d.match(re) || [])[1] || '';
        summons.push({ ts: e.ts, lane: g(/lane=(\S+)/), vendor: g(/vendor=(\S+)/), model: g(/model=(\S+)/), route: g(/route=(\S+)/), cost_usd: Number(g(/cost=\$([0-9.]+)/)) || 0 });
      }
    } catch (e) {}
  }
} catch (e) {}

const selfDrive = /self_drive_implemented:\s*true/.test(read(BUNDLE + '/charter/charter.yml'));

return [{ json: {
  ok: true,
  generated_at: new Date().toISOString(),
  self_drive_implemented: selfDrive,
  brakes: { kill_switch: killSwitch, armed, wake_summon: wakeSummon, concurrency_lock: lock,
    budget: { per_task_usd: perTask, daily_usd: daily, spent_usd: spent, remaining_usd: Math.max(0, daily - spent) } },
  handoffs, scheduled_wakes: handoffs, summons, events,
} }];

// Wake-orchestrator control API -- flips the bundle's brake state files. Bearer-
// gated + mirrors the shell scripts' preconditions (arm refuses unless kill clear
// + budgets set; wake-arm refuses unless armed too). Every action writes an audit
// event. Ships behind active:false; the bundle ships kill-switch ENGAGED.
const fs = require('fs');
const BUNDLE = process.env.WAKE_BUNDLE_DIR || '/data/poetech-portable';
const STATE = BUNDLE + '/state';
const BEARER_FILE = '/home/node/.n8n/n8n-webhook-bearer.txt';
function exists(p){ try { fs.accessSync(p); return true; } catch (e) { return false; } }
function read(p){ try { return fs.readFileSync(p, 'utf8'); } catch (e) { return ''; } }
function touch(p, c){ try { fs.writeFileSync(p, c); } catch (e) {} }
function rm(p){ try { fs.unlinkSync(p); } catch (e) {} }
function logEvent(ev, detail){ try { fs.appendFileSync(BUNDLE + '/events/events.jsonl', JSON.stringify({ ts: new Date().toISOString(), node: 'wf-control', agent: 'wake-control', event: ev, detail }) + '\n'); } catch (e) {} }

const expected = read(BEARER_FILE).trim();
const input = $input.first().json || {};
const headers = (input.headers && typeof input.headers === 'object') ? input.headers : {};
const auth = String(headers.authorization || headers.Authorization || '');
const presented = auth.replace(/^Bearer\s+/i, '').trim();
if (expected && presented !== expected) return [{ json: { ok: false, error: 'unauthorized' } }];

const body = (input.body && typeof input.body === 'object') ? input.body : {};
const action = String(body.action || '').toLowerCase();
const KILL = STATE + '/KILL_SWITCH', ARMED = STATE + '/ARMED', WS = STATE + '/WAKE_SUMMON';
const stamp = new Date().toISOString();
const env = read(BUNDLE + '/.env');
function envNum(k){ const m = env.match(new RegExp('^' + k + '\\s*=\\s*([0-9.]+)', 'm')); return m ? Number(m[1]) : 0; }
const budgetsSet = envNum('BUDGET_PER_TASK_USD') > 0 && envNum('BUDGET_DAILY_USD') > 0;

let result;
switch (action) {
  case 'kill': touch(KILL, 'ENGAGED via cockpit ' + stamp + '\n'); rm(ARMED); rm(WS); result = 'kill-switch engaged (panic stop)'; break;
  case 'unkill': rm(KILL); result = 'kill-switch disengaged'; break;
  case 'arm':
    if (exists(KILL)) return [{ json: { ok: false, error: 'refused: kill-switch engaged' } }];
    if (!budgetsSet) return [{ json: { ok: false, error: 'refused: budgets not set in .env' } }];
    touch(ARMED, 'ARMED via cockpit ' + stamp + '\n'); result = 'armed'; break;
  case 'disarm': rm(ARMED); rm(WS); result = 'disarmed'; break;
  case 'wake-arm':
    if (exists(KILL)) return [{ json: { ok: false, error: 'refused: kill-switch engaged' } }];
    if (!exists(ARMED)) return [{ json: { ok: false, error: 'refused: not armed' } }];
    if (!budgetsSet) return [{ json: { ok: false, error: 'refused: budgets not set' } }];
    touch(WS, 'WAKE_SUMMON via cockpit ' + stamp + '\n'); result = 'wake-summon consented'; break;
  case 'wake-disarm': rm(WS); result = 'wake-summon withdrawn'; break;
  default: return [{ json: { ok: false, error: 'unknown action: ' + action } }];
}
logEvent('control_' + action, result + ' (via in-app cockpit)');
return [{ json: { ok: true, action, result, brakes: { kill_switch: exists(KILL) ? 'engaged' : 'clear', armed: exists(ARMED), wake_summon: exists(WS) } } }];
